/**
 * Flat dependency resolution over an in-memory registry: one version per
 * package, chosen highest-first, with a conflict report naming the chain that
 * imposed each constraint.
 */
import { ResolveError, compareVersions, parseRange, parseVersion, satisfies } from './semver.js';

/** Raised when no version of a package satisfies everything asked of it. */
export class ConflictError extends ResolveError {
  /**
   * @param {string} packageName Package that could not be satisfied.
   * @param {Array<{range: string, via: string}>} constraints Every constraint on it, in the order they arrived.
   * @param {string[]} available Versions the registry offers, ascending.
   */
  constructor(packageName, constraints, available) {
    const detail = constraints.map((entry) => `${entry.range} (from ${entry.via})`).join(', ');
    super('CONFLICT', `cannot satisfy ${packageName}: ${detail}`);
    this.name = 'ConflictError';
    this.packageName = packageName;
    this.constraints = constraints;
    this.available = available;
  }
}

/**
 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function validateDependencies(deps, label) {
  if (!isPlainObject(deps)) {
    throw new ResolveError('BAD_DEPENDENCIES', `${label} must be an object`);
  }
  for (const range of Object.values(deps)) {
    parseRange(range);
  }
}

function validateRegistry(registry) {
  if (!isPlainObject(registry)) {
    throw new ResolveError('BAD_REGISTRY', 'registry must be an object');
  }
  for (const [name, entry] of Object.entries(registry)) {
    if (!isPlainObject(entry)) {
      throw new ResolveError('BAD_REGISTRY', `registry entry must be an object: ${name}`);
    }
    for (const [version, metadata] of Object.entries(entry)) {
      parseVersion(version);
      if (!isPlainObject(metadata)) {
        throw new ResolveError('BAD_REGISTRY', `metadata must be an object: ${name}@${version}`);
      }
      if (metadata.deps !== undefined) {
        validateDependencies(metadata.deps, `dependencies of ${name}@${version}`);
      }
    }
  }
}

/**
 * Resolve one version per package.
 *
 * @param {Record<string, Record<string, {deps?: Record<string, string>}>>} registry Available packages.
 * @param {Record<string, string>} rootDeps Ranges the root asks for.
 * @returns {{resolved: Record<string, string>, order: string[]}} Selection and the order it was made in.
 */
export function resolve(registry, rootDeps) {
  validateRegistry(registry);
  validateDependencies(rootDeps, 'root dependencies');

  const constraints = new Map(); // name -> [{ range, via }]
  const selected = new Map(); // name -> version
  const chains = new Map(); // name -> chain string
  const pending = new Set();
  const order = [];

  function addConstraint(name, range, via) {
    if (!constraints.has(name)) constraints.set(name, []);
    constraints.get(name).push({ range, via });
    if (!selected.has(name)) pending.add(name);
  }

  for (const name of Object.keys(rootDeps).sort()) {
    addConstraint(name, rootDeps[name], '<root>');
  }

  while (pending.size > 0) {
    const name = [...pending].sort()[0];
    pending.delete(name);

    if (!(name in registry)) {
      throw new ResolveError('UNKNOWN_PACKAGE', `unknown package: ${name}`);
    }

    const entries = registry[name];
    const available = Object.keys(entries).sort(compareVersions);
    const nameConstraints = constraints.get(name) ?? [];

    const candidates = available.filter((version) =>
      nameConstraints.every((c) => satisfies(version, c.range)),
    );

    if (candidates.length === 0) {
      throw new ConflictError(name, nameConstraints, available);
    }

    const chosen = candidates[candidates.length - 1];
    selected.set(name, chosen);
    order.push(name);

    const origin = nameConstraints[0].via;
    const chain = `${origin} > ${name}@${chosen}`;
    chains.set(name, chain);

    const deps = entries[chosen].deps ?? {};
    for (const depName of Object.keys(deps).sort()) {
      addConstraint(depName, deps[depName], chain);

      if (selected.has(depName)) {
        const depVersion = selected.get(depName);
        if (!satisfies(depVersion, deps[depName])) {
          throw new ConflictError(depName, constraints.get(depName), Object.keys(registry[depName] ?? {}).sort(compareVersions));
        }
      }
    }
  }

  const resolved = {};
  for (const name of [...selected.keys()].sort()) {
    resolved[name] = selected.get(name);
  }

  return { resolved, order };
}
